SELECT t.label FROM (
    SELECT 'ecom.label.dev.offer' AS label, 1 AS ord FROM ecom_1688_offer WHERE material_id = #{id}
    UNION ALL SELECT 'ecom.label.dev.aliOrder', 2 FROM ecom_1688_order_item WHERE material_id = #{id}
) t ORDER BY t.ord LIMIT 1

SELECT t.label FROM (
    SELECT 'ecom.label.dev.sample' AS label, 1 AS ord FROM ecom_dev_sample WHERE supplier_id = #{id}
    UNION ALL SELECT 'ecom.label.dev.offer', 2 FROM ecom_1688_offer WHERE supplier_id = #{id}
) t ORDER BY t.ord LIMIT 1

SELECT 'ecom.label.dev.sample' AS label_key, COUNT(*) AS total, 0 AS conflicts FROM ecom_dev_sample WHERE supplier_id IN
#{id}
UNION ALL
SELECT 'ecom.label.dev.offer', COUNT(*), 0 FROM ecom_1688_offer WHERE supplier_id IN
#{id}
